import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const resources = {
    textures: [],
    geometries: [],
    materials: [],
  };

  // Load and display image texture as textured plane
  if (config.assets?.imageUrl) {
    const texture = ctx.textureLoader.load(config.assets.imageUrl);
    texture.colorSpace = THREE.SRGBColorSpace;
    resources.textures.push(texture);

    const geometry = new THREE.PlaneGeometry(5.12, 3.2);
    resources.geometries.push(geometry);

    const material = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      side: THREE.DoubleSide,
    });
    resources.materials.push(material);

    const plane = new THREE.Mesh(geometry, material);
    group.add(plane);
  }

  // Render text content using MSDF font atlas
  if (config.textContent) {
    const textMesh = ctx.fontAtlas.createTextMesh(
      config.textContent,
      {
        font: 'JetBrains Mono',
        fontSize: 0.13,
        fontWeight: 400,
        color: 0xe8ecf2,
        align: 'left',
      }
    );
    textMesh.position.set(-2.0, 1.0, 0.05);
    group.add(textMesh);
  }

  // Apply scene position with spec defaults
  const {
    x = 0,
    y = 3,
    z = 0,
    rotationXYZ = [0, 0, 0],
    scaleXYZ = [1, 1, 1],
  } = config.scenePosition || {};

  group.position.set(x, y, z);
  group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
  group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);

  // Apply cinematic primitives
  if (config.cinematicPrimitives?.length > 0) {
    for (const primitive of config.cinematicPrimitives) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  // Cleanup function
  group.userData.cleanup = () => {
    resources.geometries.forEach(g => g.dispose());
    resources.materials.forEach(m => m.dispose());
    resources.textures.forEach(t => t.dispose());
    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
